CF2081D MST in Modulo Graph
思路分析
首先思考暴力，考虑给 \(n\) 个点两两连边，总共 \(n^2\) 条边。然后思考这些边哪些需要保留，很明显，边权小的优先保留，才能使最终总边权最小。那这不就是一个最小生成树吗？直接 Kruskal 处理即可。
但是这道题数据范围：
\(1 \le n \le 5 \times 1e5\)
直接时间空间双炸好吧。
观察数据范围，看到这题的 \(p_i\) 尤为的小，考虑从这儿入手。
首先建边优化。我们发现我们建了许多无用的边，导致最终空间炸了，思考如何减少这种无用的边。
这道题的边权计算比较特殊，而我们又需要边权尽量小的边，不妨先设两个点的边权为 \(x,y\) 。为了方便计算，我们先令 \(x \ge y\)。所以这两点的边权就为 \(x \bmod y\) 。要使边权尽量小，我们就需要尽量让 \(x\) 接近 \(y\) 的倍数。
再设一值 \(k\) 表示 \(y\) 的多少倍。这里的 \(k \times y\) 是第一个小于 \(x\) 的数，所以边权可表示为 \((x-k \times y)\) 。
假设给定了 \(k,y\) ，又有两个数 \(m，n\) ， \(k \times y \le m \le n \le y \times (k+1)\) 。此时若 \(y\) 与 \(m,n\) 建边，边权是固定好了的。与 \(m\) 建边的代价是 \(m - k \times y\) ，与 \(n\) 建边的代价是 \(n - k \times y\) 。但是由于 \(m \le n\) ，我们肯定要优先考虑与 \(m\) 建边。那 \(y\) 到底要不要与 \(n\) 建边呢？答案是不用的。为什么？
还是刚刚的值，如果 \(y\) 和 \(m,n\) 两点各建一条边，那么总代价是 \((m - k \times y)+(n - k \times y)\) 。但如果是 \(y\) 与 \(m\) 建边， \(m\) 与 \(n\) 建边，那么总代价就是 \((m - k \times y)+(n - m)\) ，很明显，代价要小一些。所以建边不就可以省去多余点了。
遍历 \(p_i\) ，然后再枚举 \(k\) 倍 \(p_i\) 。对于每个 \(k \times p_i\) ，二分第一个小于它的，然后看他是否在 \(p_i \times (k-1)\) ~ \(p[i] \times k\) ，如果在就把这个边加入。最后跑一下 Kruskal 就行了。
然后交上去还是错误，发现TLE。如果是许多个 \(1\) ，那么跑倍数就要跑 \(n\) 次，这样时间就直接接近 \(n^2\) 了。
思考优化。\(p_i\) 相同的可以直接两两连边，边权为 \(0\) ，然后再缩成一个点，其实就是去一遍重，最后就A了。
时间分析：大概是 \(O(n \log^2 n)\)，可以通过。
代码
AC记录
//#pragma GCC optimize("Ofast,unroll-all-loops")
#include <bits/stdc++.h>
using namespace std;
#define DEBUG
#ifdef DEBUG
#define bug clog
#else
#define bug while(false) clog
#endif
using ll = long long;
using ull = unsigned long long;
namespace CJRcn {
#ifdef _WIN32
#define getchar_unlocked getchar
#define putchar_unlocked putchar
#endif
#define gtc getchar_unlocked
#define ptc putchar_unlocked
	void kc(int& c){c=gtc();while(c!=EOF&&c<=' ')c=gtc();}template<typename T>void read(T& x){x=0;int c=0,f=0;kc(c);if(c=='-')f=1,c=gtc();while(c>='0'&&c<='9'){x=x*10+c-'0';c=gtc();}if(f)x=-x;}void read(char& x){int c=0;kc(c);x=c;}void read(string& x){int c=0;kc(c);x.clear();while(c!=EOF&&c>' '){x.push_back(c);c=gtc();}}void read(bool& x){int c=0;kc(c);x=c-'0';}template<typename T>void write(const T& x){if(x==0){ptc('0');return;}T y=x;if(y<0)ptc('-'),y=-y;char s[64]={};int len=0;while(y){s[len++]=y%10+'0';y/=10;}while(len--)ptc(s[len]);}void write(char x){ptc(x);}void write(bool x){ptc(x+'0');}void write(const string& x){for(char c:x)ptc(c);}void write(const char* x){while(*x)ptc(*x++);}template<typename T1,typename T2,typename... T3>void read(T1& x,T2& y,T3&... z){read(x);read(y,z...);}template<typename T1,typename T2,typename... T3>void write(const T1& x,const T2& y,const T3&... z){write(x);write(y,z...);}struct Fin{template<typename T>Fin& operator>>(T& x){read(x);return *this;}}fin;struct Fout{template<typename T>Fout& operator<<(const T& x){write(x);return *this;}}fout;}using namespace CJRcn;
#define cin fin
#define cout fout
#define pr pair<ll,ll>
#define ll long long
const int N=5e5+5;
int p[N],cnt[N],fa[N];
struct node
{
	int u,v,w;
	friend bool operator <(const node &x,const node &y){return x.w<y.w;}    // 按边权从下到大排序 
};
vector<node>a;
int find(int x){return ((x==fa[x])?x:fa[x]=find(fa[x]));}   // 并查集路径压缩 
inline void merge(int x,int y){fa[find(y)]=find(x);}  // 两点之间连边 
signed main()
{
	int T; cin >>T;
	while (T--)
	{ 
		/*
		这里pcnt就是去重完以后的p的总个数
		*/
		int n,pcnt=0; cin >>n;
		for (int i=1;i<=n;i++)
		{
			int x;cin >>x;
			if (!cnt[x]) p[++pcnt]=x;  // 如果这个 
			cnt[x]++;
		}
		// cnt没有用了，直接在这儿清空了，后面就不用遍历全部了 
		for (int i=1;i<=pcnt;i++) fa[i]=i,cnt[p[i]]=0;  
		sort(p+1,p+pcnt+1);  // p按照值从小到大排序，方便后面二分（具有单调性） 
		for (int i=1;i<=pcnt;i++)
		{

			// 范围：p[i]*(k-1)~p[i]*k 
			for (int k=1;k<=p[pcnt]/p[i]+1;k++)  // 遍历 k ，k 表示 p[i] 的多少倍 
			{
				int l,r,ans=0;
				/*
				这里如果 k==1 ，将 k 套入上面范围可看出此时范围是 0~p[i]的
				又因为前面p已经从小到大所以直接 1~i-1 的范围二分就行了
				反之就是 i+1~pcnt 
				*/
				if (k==1) l=1,r=i-1;   
				else l=i+1,r=pcnt;
				while (l<=r)  // 二分查找 >=p[i]*(k-1)的最小值 
				{
					int mid=(l+r)>>1;
					if (p[mid]>=p[i]*(k-1)) r=mid-1,ans=mid;
					else l=mid+1;
				}
				if (ans==0) continue;
				// 找到  >=p[i]*(k-1)的最小值 但是有可能这个最小值超过了上界 p[i]*k ，所以需要判断一下 
				// 关于连边：这样连相当于直接把边放进一个数组中了，到时候方便按照 w 排序 还方便遍历 
				if (p[i]*(k-1)<=p[ans] && p[ans]<=p[i]*k) a.push_back({i,ans,max(p[i],p[ans])%min(p[i],p[ans])}); // 是的话直接连边 
			}
		}
		sort(a.begin(),a.end());  // 按边权排序 
		// Kruskal 
		ll ans=0;
		for (auto [u,v,w]:a)
		{
			if (find(u)==find(v)) continue;   // 如果双方父亲相同，在一个联通快上直接跳过就行了 
			merge(u,v);ans+=w;   // 如果双方父亲不相同就连边，答案就要加上他们连边的边权 
		}
		cout <<ans<<'\n';   // 输出最终的代价 
		a.clear();  //清空 a 数组，方便下一次遍历
	 } 
	return 0;
}
